using System;
using System.IO;
using System.Linq;
using System.IO.Compression;
using System.Threading.Tasks;
using System.Collections.Generic;
using Orbit;
class SupportTests {
 static int count;static string root=Path.Combine(Path.GetTempPath(),"Orbit Support "+Guid.NewGuid());
 static string Dir(){var p=Path.Combine(root,Guid.NewGuid().ToString());Directory.CreateDirectory(p);return p;}
 static void Yes(bool b){if(!b)throw new Exception("Assertion failed");}
 static void Check(string label,Action action){action();count++;Console.WriteLine("PASS "+label);}
 static void ThrowSecret(){throw new InvalidOperationException("AIzaSECRET prompt=private account=someone cookie=secret /home/user/file");}
 static void Main(){Directory.CreateDirectory(root);try{
  Check("structured event id and UTC",()=>{var d=Dir();var log=new DiagnosticsLog(d,"app");var id=log.Record("game.started");var e=DiagnosticsLog.Read(d).Single();Yes(e.id==id&&Guid.TryParse(id,out _)&&e.name=="game.started"&&e.timeUtc.EndsWith("+00:00"));});
  Check("exception values never logged",()=>{var d=Dir();var log=new DiagnosticsLog(d,"app");try{ThrowSecret();}catch(Exception ex){ex.Data["password"]="hunter2";log.Record("ui.callback.failed",ex);}var text=File.ReadAllText(Path.Combine(d,"orbit.jsonl"));Yes(!text.Contains("SECRET")&&!text.Contains("hunter2")&&!text.Contains("private")&&!text.Contains("/home/"));var e=DiagnosticsLog.Read(d).Single();Yes(e.exceptionType=="System.InvalidOperationException"&&e.hresult!=null);});
  Check("nested exception signature",()=>{var d=Dir();new DiagnosticsLog(d,"app").Record("app.task.failed",new AggregateException(new IOException("secret")));Yes(DiagnosticsLog.Read(d).Single().exceptionType=="System.IO.IOException");});
  Check("unknown event/component values discarded",()=>{var d=Dir();new DiagnosticsLog(d,"app").Record("api-key-secret",component:"private-user");var text=File.ReadAllText(Path.Combine(d,"orbit.jsonl"));Yes(!text.Contains("api-key")&&!text.Contains("private-user"));Yes(DiagnosticsLog.Read(d).Single().name=="event.unknown");});
  Check("repeated failure throttled with same correlation id",()=>{var d=Dir();var log=new DiagnosticsLog(d,"app");var a=log.Record("downloads.failed");var b=log.Record("downloads.failed");Yes(a==b&&DiagnosticsLog.Read(d).Length==1);});
  Check("rotation bounded to three files per channel",()=>{var d=Dir();var log=new DiagnosticsLog(d,"app");for(int n=0;n<7000;n++)log.Record("ui.error",number:n);var files=Directory.GetFiles(d);Yes(files.Length==3&&files.All(p=>new FileInfo(p).Length<=DiagnosticsLog.MaxBytes));Yes(DiagnosticsLog.Read(d).Length>0);});
  Check("concurrent events produce complete JSON rows",()=>{var d=Dir();var log=new DiagnosticsLog(d,"app");Parallel.For(0,100,n=>log.Record("ui.error",number:n));Yes(DiagnosticsLog.Read(d).Length==100);});
  Check("logging failure never escapes and recovers",()=>{var d=Dir();var bad=Path.Combine(d,"not-a-directory");File.WriteAllText(bad,"blocked");var log=new DiagnosticsLog(bad,"app");log.Record("app.started");Yes(!log.Writable);File.Delete(bad);log.Record("browser.ready");Yes(log.Writable&&DiagnosticsLog.Read(bad).Length==1);});
  Check("read only known log file names and ignore malformed rows",()=>{var d=Dir();var log=new DiagnosticsLog(d,"app");log.Record("app.started");File.AppendAllText(Path.Combine(d,"orbit.jsonl"),"broken\n");File.WriteAllText(Path.Combine(d,"secrets.jsonl"),"APIKEY");Yes(DiagnosticsLog.Read(d).Length==1);});
  Check("unknown JSON properties removed on export read",()=>{var d=Dir();var log=new DiagnosticsLog(d,"app");log.Record("app.started");var file=Path.Combine(d,"orbit.jsonl");var text=File.ReadAllText(file).Replace("{","{\"secret\":\"private\",");File.WriteAllText(file,text);Yes(!DiagnosticJson.Write(DiagnosticsLog.Read(d)).Contains("private"));});
  Check("tail is bounded and starts at a whole line",()=>{var d=Dir();var p=Path.Combine(d,"file");File.WriteAllText(p,"old-secret\n"+new string('x',1000)+"\nlast-line\n");var tail=DiagnosticsLog.Tail(p,20);Yes(tail=="last-line\n");});
  Check("engine signals exclude account URLs and general hex values",()=>{var d=Dir();File.WriteAllText(Path.Combine(d,"playnite.log"),"cookie=private url=https://example.test/?key=secret key=0xDEADBEEF\nBadImageFormatException libcef.dll\nHResult: 0x8007000B\n");var x=SupportBundle.Signals(d);var json=DiagnosticJson.Write(x);Yes(x.exceptionTypes.Contains("BadImageFormatException")&&x.components.Contains("libcef.dll")&&x.hresults.SequenceEqual(new[]{"0X8007000B"}));Yes(!json.Contains("private")&&!json.Contains("secret")&&!json.Contains("example")&&!json.Contains("DEADBEEF"));});
  Check("missing engine log reported honestly",()=>Yes(SupportBundle.Signals(Dir()).status=="not-found"));
  Check("ZIP contains only four named safe entries",()=>{var d=Dir();var log=new DiagnosticsLog(Path.Combine(d,"Logs"),"app");log.Record("app.started");File.WriteAllText(Path.Combine(d,"preferences.json"),"secret");File.WriteAllText(Path.Combine(d,"game-journal.json"),"secret-note");File.WriteAllText(Path.Combine(d,"minecraft-settings.json"),"secret-profile-path");var output=Path.Combine(d,"report.zip");SupportBundle.Create(d,output,log,new SupportContext{games=12,installed=3});using(var z=ZipFile.OpenRead(output)){Yes(z.Entries.Select(x=>x.FullName).OrderBy(x=>x).SequenceEqual(new[]{"README.txt","orbit-events.jsonl","playnite-signals.json","summary.json"}.OrderBy(x=>x)));foreach(var e in z.Entries)using(var r=new StreamReader(e.Open()))Yes(!r.ReadToEnd().Contains("secret"));}});
  Check("export rebuilds records and drops injected fields",()=>{var d=Dir();var log=new DiagnosticsLog(Path.Combine(d,"Logs"),"app");log.Record("app.started");var file=Path.Combine(log.DirectoryPath,"orbit.jsonl");File.WriteAllText(file,File.ReadAllText(file).Replace("{","{\"prompt\":\"DO_NOT_EXPORT\","));var output=Path.Combine(d,"report.zip");SupportBundle.Create(d,output,log,new SupportContext());using(var z=ZipFile.OpenRead(output))using(var r=new StreamReader(z.GetEntry("orbit-events.jsonl").Open()))Yes(!r.ReadToEnd().Contains("DO_NOT_EXPORT"));});
  Check("successful replacement is atomic and leaves no temp file",()=>{var d=Dir();var output=Path.Combine(d,"report.zip");File.WriteAllText(output,"old");var log=new DiagnosticsLog(Path.Combine(d,"Logs"),"app");SupportBundle.Create(d,output,log,new SupportContext());using(var z=ZipFile.OpenRead(output))Yes(z.Entries.Count==4);Yes(Directory.GetFiles(d,"*.partial-*").Length==0);});
  Check("failed replacement keeps target and cleans partial",()=>{var d=Dir();var target=Path.Combine(d,"report.zip");Directory.CreateDirectory(target);var sentinel=Path.Combine(target,"keep");File.WriteAllText(sentinel,"original");try{SupportBundle.Create(d,target,new DiagnosticsLog(Path.Combine(d,"Logs"),"app"),new SupportContext());throw new Exception("Expected failure");}catch(IOException){}Yes(File.ReadAllText(sentinel)=="original"&&Directory.GetFiles(d,"*.partial-*").Length==0);});
  Check("two channels have independent sessions",()=>{var d=Dir();new DiagnosticsLog(d,"bootstrap").Record("startup.begin");new DiagnosticsLog(d,"app").Record("app.started");var e=DiagnosticsLog.Read(d);Yes(e.Length==2&&e[0].session!=e[1].session);});
  Console.WriteLine(count+" SUPPORT CHECKS PASSED");
 }finally{Directory.Delete(root,true);}}
}
